import React, { useMemo } from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  interpolate,
  spring,
  Easing,
} from '../remotionShim';
{/* Start Google Fonts Loader */ }
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700;800`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */ }



export type RevenueMultiplierProps = Record<string, any>;

const RevenueMultiplier: React.FC<RevenueMultiplierProps> = ({
  backgroundColor = "#0A0A0A",
  transparentBackground = false,
  durationInSeconds = 3,
  text1 = "YOUR REVENUE",
  text2 = "×10",
  primaryColor = "#FFFFFF",
  accentColor = "#CCBA78",
  text1Size = 80,
  text2Size = 180,
  glowIntensity = 0.6,
}) => {
  useFontLoader(["Montserrat"]);

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Logic to prevent parser errors
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // --- TIMING ---
  const shiftStartFrame = fps * 1.5; // When Text 1 moves over

  // --- ANIMATION: TEXT 1 (YOUR REVENUE) ---
  // Entrance: Slide in from Left to Center
  const text1Entrance = spring({
    frame,
    fps,
    config: { damping: 14, stiffness: 100 },
  });

  // Shift: Move UP to allow Text 2 to enter
  const text1Shift = spring({
    frame: frame - shiftStartFrame,
    fps,
    config: { damping: 14, stiffness: 80 },
  });

  // X Position: Enters from left, stays centered
  const text1X = interpolate(
    text1Entrance,
    [0, 1],
    [-width * 0.6, 0]
  );

  // Y Position: Starts centered (0), then moves up (-150)
  const text1Y = interpolate(
    text1Shift,
    [0, 1],
    [0, -140]
  );

  // --- ANIMATION: TEXT 2 (x10) ---
  // Enters shortly after Text 1 begins to move
  const text2StartFrame = shiftStartFrame + 5;

  const text2Entrance = spring({
    frame: frame - text2StartFrame,
    fps,
    config: { damping: 12, stiffness: 100, mass: 1.2 },
  });

  // Enters from bottom (+offset) to resting position (+50)
  // This creates a "slide up into slot" effect
  const text2Y = interpolate(
    text2Entrance,
    [0, 1],
    [300, 60] // Start lower, land just below center
  );

  const text2Scale = interpolate(
    text2Entrance,
    [0, 0.8, 1],
    [0.8, 1.05, 1] // Subtle overshoot scale
  );

  const text2Opacity = interpolate(
    text2Entrance,
    [0, 0.4],
    [0, 1],
    { extrapolateRight: "clamp" }
  );


  // --- ANIMATION: BACKGROUND ---
  // Glow Animation
  const glowDriftX = interpolate(frame, [0, durationInSeconds * fps], [0, 50]);
  const glowDriftY = interpolate(frame, [0, durationInSeconds * fps], [0, -30]);
  const glowPulse = interpolate(
    Math.sin(frame / 20),
    [-1, 1],
    [0.9, 1.1]
  );

  // Styles
  const containerStyle: React.CSSProperties = {
    fontFamily: "Montserrat",
    fontWeight: 800,
    width: "100%",
    height: "100%",
    display: "flex",
    justifyContent: "center",
    alignItems: "center",
    position: "relative",
    overflow: "hidden",
  };

  // Dynamic Grid Background (Static Position)
  const gridStyle: React.CSSProperties = {
    position: "absolute",
    top: -100,
    left: -100,
    right: -100,
    bottom: -100,
    backgroundImage: `
      linear-gradient(to right, ${primaryColor}15 1px, transparent 1px),
      linear-gradient(to bottom, ${primaryColor}15 1px, transparent 1px)
    `,
    backgroundSize: "60px 60px",
    maskImage: "radial-gradient(circle at center, black 40%, transparent 90%)", // Fade grid edges
    WebkitMaskImage: "radial-gradient(circle at center, black 40%, transparent 90%)",
    zIndex: 1,
  };

  const glowStyle: React.CSSProperties = {
    position: "absolute",
    width: width * 1.5,
    height: height * 1.5,
    background: `radial-gradient(circle, ${accentColor}40 0%, transparent 60%)`,
    left: "50%",
    top: "50%",
    transform: `translate(-50%, -50%) translate(${glowDriftX}px, ${glowDriftY}px) scale(${glowPulse})`,
    opacity: glowIntensity,
    filter: "blur(80px)",
    zIndex: 0, // Behind grid
  };

  const textWrapperStyle: React.CSSProperties = {
    position: "absolute",
    display: "flex",
    justifyContent: "center",
    alignItems: "center",
    width: "100%",
    textAlign: "center",
    zIndex: 3, // Above grid and glow
    willChange: "transform, opacity",
  };

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor }}>
      <div style={containerStyle}>

        {/* Dynamic Glow */}
        <div style={glowStyle} />

        {/* Gridded Background */}
        <div style={gridStyle} />

        {/* Text 1: YOUR REVENUE */}
        {/* Moves up to make room */}
        <div
          style={{
            ...textWrapperStyle,
            transform: `translate(${text1X}px, ${text1Y}px)`,
          }}
        >
          <h1
            style={{
              color: primaryColor,
              fontSize: text1Size,
              margin: 0,
              letterSpacing: "-0.02em",
              textShadow: "0px 4px 20px rgba(0,0,0,0.5)",
              whiteSpace: "nowrap",
            }}
          >
            {text1}
          </h1>
        </div>

        {/* Text 2: x10 */}
        {/* Enters below Text 1 */}
        <div
          style={{
            ...textWrapperStyle,
            transform: `translateY(${text2Y}px) scale(${text2Scale})`,
            opacity: text2Opacity,
          }}
        >
          <h1
            style={{
              color: accentColor,
              fontSize: text2Size,
              margin: 0,
              letterSpacing: "-0.04em",
              textShadow: `0px 10px 40px ${accentColor}60`,
              whiteSpace: "nowrap",
            }}
          >
            {text2}
          </h1>
        </div>

      </div>
    </AbsoluteFill>
  );
};

export default RevenueMultiplier;